import pulp

# Define the operations for each job (D1 to D4)
jobs = [
    [(4, 9), (1, 8), (2, 6), (3, 8)],  # D1
    [(4, 1), (3, 6), (1, 6), (2, 6)],  # D2
    [(1, 10), (3, 3), (4, 7), (2, 10)], # D3
    [(3, 2), (4, 9), (2, 1), (1, 2)]   # D4
]

n_jobs = len(jobs)
n_ops = len(jobs[0])

# Create the model
model = pulp.LpProblem("Job_Shop_Scheduling", pulp.LpMinimize)

# Decision variables: start times for each job and operation
start = {}
end = {}
for j in range(n_jobs):
    for i in range(n_ops):
        start[(j, i)] = pulp.LpVariable(f"start_{j}_{i}", lowBound=0)
        end[(j, i)] = pulp.LpVariable(f"end_{j}_{i}", lowBound=0)

# Makespan variable
makespan = pulp.LpVariable("makespan", lowBound=0)

# Build station_ops: for each station, list of (job, op_index, duration)
station_ops = {}
for j in range(n_jobs):
    for i in range(n_ops):
        station, duration = jobs[j][i]
        if station not in station_ops:
            station_ops[station] = []
        station_ops[station].append((j, i, duration))

# Big M constant (safe upper bound)
M = 200

# Binary variables for disjunctive constraints on each station
# We'll create a dict: key = (op1, op2) where op1 and op2 are (job, op_index) and op1 < op2 (lex order)
# We'll create one binary variable per unordered pair on the same station
binary_vars = {}

# For each station, generate all unordered pairs of operations
for station, ops in station_ops.items():
    # ops is list of (j, i, dur)
    n_ops_in_station = len(ops)
    for idx1 in range(n_ops_in_station):
        for idx2 in range(idx1 + 1, n_ops_in_station):
            op1 = ops[idx1]  # (j1, i1, dur1)
            op2 = ops[idx2]  # (j2, i2, dur2)
            # Create canonical key: sorted by (job, op_index)
            key = tuple(sorted([op1[:2], op2[:2]]))  # sorted by the tuple (job, op_index)
            # We don't need to store the duration, we just need the operation identifiers
            binary_vars[key] = pulp.LpVariable(f"y_{key[0]}_{key[1]}", cat='Binary')

# Precedence constraints: for each job, operation i must finish before operation i+1 starts
for j in range(n_jobs):
    for i in range(n_ops - 1):
        model += end[(j, i)] <= start[(j, i + 1)], f"precedence_{j}_{i}"

# Disjunctive constraints: for each station and each pair of operations on that station
for station, ops in station_ops.items():
    for idx1 in range(len(ops)):
        for idx2 in range(idx1 + 1, len(ops)):
            op1 = ops[idx1]  # (j1, i1, d1)
            op2 = ops[idx2]  # (j2, i2, d2)
            key = tuple(sorted([op1[:2], op2[:2]]))
            y = binary_vars[key]
            j1, i1 = op1[:2]
            j2, i2 = op2[:2]
            # Constraint 1: if y=1, then op1 before op2: start[op2] >= end[op1]
            # if y=0, then op2 before op1: start[op1] >= end[op2]
            model += start[(j2, i2)] >= end[(j1, i1)] - M * (1 - y), f"disjunctive_{station}_{j1}_{i1}_{j2}_{i2}_1"
            model += start[(j1, i1)] >= end[(j2, i2)] - M * y, f"disjunctive_{station}_{j1}_{i1}_{j2}_{i2}_2"

# Link end times with start times and durations
for j in range(n_jobs):
    for i in range(n_ops):
        station, duration = jobs[j][i]
        model += end[(j, i)] == start[(j, i)] + duration, f"link_{j}_{i}"

# Makespan constraints: the makespan must be at least as large as the end time of every operation
for j in range(n_jobs):
    for i in range(n_ops):
        model += makespan >= end[(j, i)], f"makespan_{j}_{i}"

# Objective: minimize makespan
model += makespan

# Solve with HiGHS
model.solve(pulp.HiGHS(msg=False, timeLimit=120))

# Output the solution
print(f"Optimal makespan: {pulp.value(makespan)}")
for j in range(n_jobs):
    for i in range(n_ops):
        print(f"Job {j+1}, Op {i+1}: start={pulp.value(start[(j,i)])}, end={pulp.value(end[(j,i)])}")

