import pulp

# Define the hubs
hubs = ['Alpha', 'Beta', 'Gamma', 'Delta', 'Epsilon', 'Zeta']
n = len(hubs)

# Create a dictionary for distances between hubs
distances = {
    ('Alpha', 'Beta'): 51.0,
    ('Alpha', 'Gamma'): 48.8,
    ('Alpha', 'Delta'): 157.4,
    ('Alpha', 'Epsilon'): 202.4,
    ('Alpha', 'Zeta'): 168.3,
    ('Beta', 'Gamma'): 83.8,
    ('Beta', 'Delta'): 106.6,
    ('Beta', 'Epsilon'): 151.4,
    ('Beta', 'Zeta'): 117.6,
    ('Gamma', 'Delta'): 180.3,
    ('Gamma', 'Epsilon'): 224.3,
    ('Gamma', 'Zeta'): 189.6,
    ('Delta', 'Epsilon'): 44.9,
    ('Delta', 'Zeta'): 12.0,
    ('Epsilon', 'Zeta'): 34.7,
}

# Add reverse pairs since the graph is undirected
for (u, v), d in list(distances.items()):
    distances[(v, u)] = d

# Create the optimization model
model = pulp.LpProblem("Telecom_Ring_Optimization", pulp.LpMinimize)

# Decision variables: x[i][j] = 1 if edge between hub i and hub j is used, 0 otherwise
# We'll use indices for easier handling
hub_indices = {hub: i for i, hub in enumerate(hubs)}
x = {}
for i in range(n):
    for j in range(i+1, n):
        hub_i = hubs[i]
        hub_j = hubs[j]
        if (hub_i, hub_j) in distances:
            x[(i, j)] = pulp.LpVariable(f"x_{i}_{j}", 0, 1, cat='Binary')
        else:
            # If not in distances, it means we don't have a direct connection (shouldn't happen here but for safety)
            # We'll still create the variable with a very high cost to discourage use
            x[(i, j)] = pulp.LpVariable(f"x_{i}_{j}", 0, 1, cat='Binary')

# Objective function: minimize total propagation delay
objective = 0
for i in range(n):
    for j in range(i+1, n):
        hub_i = hubs[i]
        hub_j = hubs[j]
        if (hub_i, hub_j) in distances:
            objective += x[(i, j)] * distances[(hub_i, hub_j)]
model += objective

# Constraints:

# Each hub must have exactly two connections (since it's a cycle: degree 2 for each node)
for i in range(n):
    degree_constraint = 0
    for j in range(n):
        if i != j:
            # We need to find the correct key in x: (min(i,j), max(i,j))
            if i < j:
                key = (i, j)
            else:
                key = (j, i)
            if key in x:
                degree_constraint += x[key]
    model += degree_constraint == 2, f"degree_{hubs[i]}"

# Ensure that the solution forms a single cycle (no subtours) using Miller-Tucker-Zemlin (MTZ) formulation
# Since n=6 is small, we can use MTZ with auxiliary variables
u = {}
for i in range(n):
    u[i] = pulp.LpVariable(f"u_{i}", 0, n-1, cat='Integer')

# For hub 0 (Alpha), set u[0] = 0 (reference)
model += u[0] == 0, "u_Alpha_zero"

# For each pair (i,j), if edge (i,j) exists, then u[i] - u[j] + (n-1)*x[i][j] <= n-2
# This prevents subtours
for i in range(n):
    for j in range(1, n):  # j from 1 to n-1 to avoid u[0] constraint twice
        if i != j:
            if i < j:
                key = (i, j)
            else:
                key = (j, i)
            if key in x:
                model += u[i] - u[j] + (n-1) * x[key] <= n-2, f"MTZ_{hubs[i]}_{hubs[j]}"

# Solve the model
model.solve(pulp.HiGHS(msg=False, timeLimit=120))

# Output the solution
if pulp.LpStatus[model.status] == "Optimal":
    total_delay = pulp.value(model.objective)
    print(f"Optimal total propagation delay: {total_delay:.1f} ms")
    print("Edges in the optimal ring:")
    for i in range(n):
        for j in range(i+1, n):
            if (i, j) in x and pulp.value(x[(i, j)]) > 0.5:
                hub_i = hubs[i]
                hub_j = hubs[j]
                print(f"{hub_i} - {hub_j}: {distances[(hub_i, hub_j)]} ms")
else:
    print("No optimal solution found.")

