import pulp

# Define the number of warehouses (nodes)
n = 4
nodes = list(range(n))  # 0: Warehouse 1, 1: Warehouse 2, 2: Warehouse 3, 3: Warehouse 4

# Define the symmetric travel time matrix (minutes)
# Using 0-indexed: nodes 0,1,2,3 correspond to warehouses 1,2,3,4
dist = [
    [0, 124.4, 102.2, 132.5],  # From Warehouse 1 (node 0) to others
    [124.4, 0, 112.0, 11.7],   # From Warehouse 2 (node 1) to others
    [102.2, 112.0, 0, 123.7],  # From Warehouse 3 (node 2) to others
    [132.5, 11.7, 123.7, 0]    # From Warehouse 4 (node 3) to others
]

# Create the optimization model
model = pulp.LpProblem("TSP", pulp.LpMinimize)

# Decision variables: binary x[i][j] indicating if we travel from i to j
x = {}
for i in nodes:
    for j in nodes:
        if i != j:  # No self-loops
            x[i, j] = pulp.LpVariable(f"x_{i}_{j}", cat='Binary')

# Decision variables: continuous u[i] for MTZ formulation (for non-depot nodes)
# We fix u[0] = 0 (depot) and only define u[1], u[2], u[3]
u = {}
for i in [1, 2, 3]:  # Non-depot nodes (warehouse 2,3,4)
    u[i] = pulp.LpVariable(f"u_{i}", lowBound=1, upBound=n-1, cat='Continuous')

# Objective function: minimize total travel time
model += pulp.lpSum(dist[i][j] * x[i, j] for i in nodes for j in nodes if i != j)

# Constraints: each warehouse is entered exactly once
for j in nodes:
    model += pulp.lpSum(x[i, j] for i in nodes if i != j) == 1, f"Enter_{j}"

# Constraints: each warehouse is left exactly once
for i in nodes:
    model += pulp.lpSum(x[i, j] for j in nodes if i != j) == 1, f"Leave_{i}"

# MTZ subtour elimination constraints: for all i,j in {1,2,3} where i != j
for i in [1, 2, 3]:
    for j in [1, 2, 3]:
        if i != j:
            model += u[i] - u[j] + n * x[i, j] <= n - 1, f"MTZ_{i}_{j}"

# Solve the model using HiGHS solver
model.solve(pulp.HiGHS(msg=False, timeLimit=120))

# Output the solution (optional: for verification)
if pulp.LpStatus[model.status] == "Optimal":
    print("Optimal tour found:")
    for i in nodes:
        for j in nodes:
            if i != j and x[i, j].value() > 0.5:
                print(f"Travel from Warehouse {i+1} to Warehouse {j+1}: {dist[i][j]:.1f} minutes")
    print(f"Total travel time: {pulp.value(model.objective):.1f} minutes")
else:
    print("No optimal solution found.")

